          <text class="metric-label">心率</text>
          <div class="metric-line">
            <text class="metric-value">{{ heartRateText }}</text>
            <text class="metric-unit">bpm</text>
          </div>
        </div>
        <div class="metric-divider"></div>
        <div class="metric">
          <text class="metric-label">压力</text>
          <div class="metric-line">
            <text class="metric-value">{{ stressText }}</text>
            <text class="metric-unit">分</text>
          </div>
        </div>
      </div>

      <text if="{{ healthMessage }}" class="health-message health-message-{{ screenViewport }}">{{ healthMessage }}</text>
      <div class="mode-buttons mode-buttons-{{ screenShape }} mode-buttons-{{ screenSize }} mode-buttons-{{ screenViewport }}">
        <div class="mode-button mode-button-{{ screenShape }} mode-button-{{ screenViewport }} steady-mode" onclick="startTraining">
          <text class="mode-kicker">放松</text>
          <text class="mode-title">稳态 60</text>
        </div>
        <div class="mode-button mode-button-{{ screenShape }} mode-button-{{ screenViewport }} boxing-mode" onclick="startBoxing">
          <text class="mode-kicker boxing-kicker">活力</text>
          <text class="mode-title">节奏拳</text>
        </div>
      </div>
      <text class="disclaimer disclaimer-{{ screenViewport }}">训练体验仅供参考，不作为医疗建议</text>
    </div>

    <div if="{{ view === 'breathing' }}" class="page breathing-page breathing-page-{{ screenShape }} breathing-page-{{ screenSize }} breathing-page-{{ screenViewport }}">
      <text class="session-label">稳态训练</text>
      <text class="remaining">{{ remainingText }}</text>

      <div class="orb-shell orb-shell-{{ screenShape }} orb-shell-{{ screenSize }} orb-shell-{{ screenViewport }}">
        <div class="breath-orb breath-orb-{{ screenViewport }} {{ breathPhase }}">
          <div class="orb-core"></div>
        </div>
      </div>

      <text class="phase-label phase-label-{{ screenViewport }}">{{ phaseLabel }}</text>
      <text class="pattern-label">{{ patternLabel }}</text>
      <div class="stop-button stop-button-{{ screenViewport }}" onclick="stopTraining">
